$('importRecipe').onclick=()=>$('recipeFile').click();$('recipeFile').onchange=async()=>{try{const file=$('recipeFile').files[0];if(!file)return;if(file.size>50000)throw Error('Recipe is too large. Choose an Aether JSON recipe under 50 KB.');recipe=validateRecipe(JSON.parse(await file.text()));selected=-1;syncUI();savedList();message('Recipe imported. Save mix to keep it on this device.');}catch(e){message('Import failed: '+e.message);}finally{$('recipeFile').value='';}};
