 if(source.data){const c=document.createElement('canvas');c.width=source.width;c.height=source.height;const cx=c.getContext('2d');cx.putImageData(new ImageData(new Uint8ClampedArray(source.data),source.width,source.height),0,0);ctx.drawImage(c,0,0,180,180);}else ctx.drawImage(source,0,0,180,180);
