 for(const m of materialCatalog){const a=assets[m.id];thumbs[m.id]={color:imageURL(a.color),normal:imageURL(a.normal),roughness:imageURL(a.surface,0),ao:imageURL(a.surface,1),height:imageURL(a.surface,2)};}buildLibrary();
