 const scene=new T.Scene(),camera=new T.PerspectiveCamera(42,1,.05,100),group=new T.Group();scene.add(group);scene.add(new T.HemisphereLight(0xcfe4ff,0x66503e,2.1));const key=new T.DirectionalLight(0xffebd1,3.4);scene.add(key);const fill=new T.DirectionalLight(0x93cfff,1.2);fill.position.set(-3,1,-3);scene.add(fill);
