 const uniforms={mixWeights:{value:new T.Vector3()},mixScale:{value:new T.Vector3()},mixHeight:{value:.35},mixNormalStrength:{value:1},mixRoughness:{value:1},mixStack:{value:1},mixMaskView:{value:0},layerSeeds:{value:new T.Vector3()},layerInvert:{value:new T.Vector3()},layerMask0:{value:new T.Vector4()},layerMask1:{value:new T.Vector4()},layerMask2:{value:new T.Vector4()}};for(let i=0;i<3;i++)for(const field of ['Color','Normal','Surface'])uniforms['mix'+field+i]={value:assets.rock[field.toLowerCase()]};
