 viewport.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};viewport.setPointerCapture(e.pointerId);});viewport.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;yaw-=(e.clientX-drag.x)*.008;elevation=T.MathUtils.clamp(elevation+(e.clientY-drag.y)*.008,-1.3,1.3);drag.x=e.clientX;drag.y=e.clientY;});for(const event of ['pointerup','pointercancel','lostpointercapture'])viewport.addEventListener(event,()=>{drag=null;});viewport.addEventListener('wheel',e=>{e.preventDefault();distance=T.MathUtils.clamp(distance*Math.exp(e.deltaY*.001),2,8);},{passive:false});
 updatePreview=()=>{const r=recipe;uniforms.mixWeights.value.set(...r.layers.map(l=>l.weight));uniforms.mixScale.value.set(...r.layers.map(l=>l.scale));uniforms.mixHeight.value=r.heightBlend;uniforms.mixNormalStrength.value=r.normalStrength;uniforms.mixRoughness.value=r.roughness;material.color.set(r.tint);uniforms.mixStack.value=r.mode==='stack'?1:0;uniforms.mixMaskView.value=Number($('previewMode').value);uniforms.layerSeeds.value.set(...r.layers.map(l=>l.mask.seed));uniforms.layerInvert.value.set(...r.layers.map(l=>l.mask.invert?1:0));r.layers.forEach((l,i)=>uniforms['layerMask'+i].value.set(maskTypes.indexOf(l.mask.type),l.mask.coverage,l.mask.scale,l.mask.softness));r.layers.forEach((l,i)=>{for(const field of ['Color','Normal','Surface'])uniforms['mix'+field+i].value=assets[l.material][field.toLowerCase()];});};updatePreview();
